class GSLMatrix:
    def __init__(self, rows, cols):
        self.matrix = gsl.gsl_matrix_alloc(rows, cols)

    def free(self):
        gsl.gsl_matrix_free(self.matrix)

    @staticmethod
    def from_numpy(np_array):
        matrix = GSLMatrix(len(np_array), len(np_array[0]))
        for i in range(matrix.rows):
            for j in range(matrix.cols):
                matrix.matrix.elem[i, j] = np_array[i][j]
        return matrix

    @staticmethod
    def to_numpy(gsl_matrix):
        np_array = np.zeros((gsl_matrix.rows, gsl_matrix.cols))
        for i in range(gsl_matrix.rows):
            for j in range(gsl_matrix.cols):
                np_array[i, j] = gsl_matrix.elem[i, j]
        return np_array

    def __getitem__(self, idx):
        return self.matrix[idx]

def compute_covariance_matrix(jacobian, epsrel):
    assert len(jacobian) == 2 and all(len(row) == len(jacobian[0]) for row in jacobian), "Jacobian must be a non-empty 2D array with equal number of rows and columns"
