    return libgslcblas.cblas_sgemm(ctypes.c_char_p(order.encode('utf-8')), ctypes.c_int(transA), ctypes.c_int(transB), ctypes.c_int(M), ctypes.c_int(N), ctypes.c_int(K), ctypes.c_double(alpha), A, ctypes.c_int(lda), B, ctypes.c_int(ldb), ctypes.c_double(beta), ldc, ctypes.c_int(0))

def matrix_multiply(A, B, M, N, K, alpha, beta):
    lda = len(A)
    ldb = len(B[0])
    ldc = max(len(A), ldb)
    C = [[0.0] * ldc for _ in range(M)]
    A_array = (
        (ctypes.c_double * lda) * len(A) for A_row in A
    )
    B_array = (
        (ctypes.c_double * ldb) * len(B) for B_col in B
    )
    C_array = (
        (ctypes.c_double * ldc) * len(C) for _ in range(len(C))
    )
    for i, A_row in enumerate(A):
        for j, value in enumerate(A_row):
            A_array[i][j] = value

    for i, B_col in enumerate(B):
        for j, value in enumerate(B_col):
            B_array[j][i] = value

    for k, C_row in enumerate(C):
        for l, _ in enumerate(C_row):
            C_array[k][l] = 0.0

    order = "C"
    transA = 0
    transB = 0
    cblas_sgemm(order, transA, transB, M, N, K, alpha, A_array[0], lda, B_array[0], ldb, beta, C_array[0], ldc)
    return [list(row) for row in C_array]

