def unpack_bidiagonal(A):
    rows, cols = len(A), len(A[0])
    matrix_A = gsl_matrix((rows, cols))
    diag = gsl_vector(rows)
    superdiag = gsl_vector(cols - 1)

    for i in range(rows):
