import ctypes

def load_gsl():
    libgslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    return libgslcblas, gsl

def create_control(libgsl, eps_abs, eps_rel, a_y, a_dydt, scale_abs, dim):
    eps_abs = ctypes.c_double(eps_abs)
    eps_rel = ctypes.c_double(eps_rel)
    a_y = ctypes.c_double(a_y)
    a_dydt = ctypes.c_double(a_dydt)
    scale_abs = (ctypes.c_double * dim)(*scale_abs)

    libgsl.gsl_odeiv2_control_scaled_new.restype = ctypes.POINTER(ctypes.c_void_p)
    control_ptr = libgsl.gsl_odeiv2_control_scaled_new(eps_abs, eps_rel, a_y, a_dydt, scale_abs, dim)

    if not ctypes.c_void_p(control_ptr).value:
        return "Error: Control object allocation failed"
    else:
        return str(ctypes.cast(control_ptr, ctypes.POINTER(ctypes.c_char_p)).contents.value)

def free_control(libgsl, control_ptr):
    libgsl.gsl_odeiv2_control_free.argtypes = [ctypes.POINTER(ctypes.c_void_p)]
    libgsl.gsl_odeiv2_control_free(ctypes.byref(control_ptr))

def main(eps_abs, eps_rel, a_y, a_dydt, scale_abs, dim):
    libgslcblas, gsl = load_gsl()

    control_str = create_control(gsl, eps_abs, eps_rel, a_y, a_dydt, scale_abs, dim)
    if "Error" in control_str:
        free_control(gsl, control_ptr)
        return {'Candidate_solution': 'Error: ' + control_str}

    try:
        control_ptr = ctypes.cast(int(control_str), ctypes.POINTER(ctypes.c_void_p))
        free_control(gsl, control_ptr)
        return {'Candidate_solution': 'Success'}
    except (ValueError, TypeError):
        free_control(gsl, control_ptr)
        return {'Candidate_solution': 'Error: Invalid control object'}

