import ctypes

class CBLAS:
    _lib = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    _lib.cblas_daxpy.argtypes = [ctypes.c_int, ctypes.c_double, ctypes.POINTER(ctypes.c_double), ctypes.c_void_p, ctypes.c_double, ctypes.POINTER(ctypes.c_double)]
class DoubleList:
    def __init__(self, data):
        self.data = (ctypes.c_double * len(data))(*data)
class Daxpy:
    @staticmethod
    def perform(N, alpha, X_list, Y_list):
        X_array = DoubleList(X_list).data
        Y_array = DoubleList(Y_list).data
        CBLAS._lib.cblas_daxpy(ctypes.c_int(N), ctypes.c_double(alpha), X_array, ctypes.byref(X_array), ctypes.c_double(1.0), Y_array)
        return list(Y_array)

